 "content": "def transform(grid):
    """Keep cells occupied on both sides of the 9 divider; recolor them 2."""
    divider = next(i for i, value in enumerate(grid[0]) if value == 9)
    left = [row[:divider] for row in grid]
    right = [row[divider + 1:] for row in grid]
    return [
        [2 if a == 7 and b == 7 else 0 for a, b in zip(lrow, rrow)]
        for lrow, rrow in zip(left, right)
    ]
